    return randomPick(options) || 'ชุดที่ประกอบด้วยสินค้าคุณภาพจากเซ็นทรัล'
  }

  // Fallback based on formality
  if (formality && formality >= 7) {
    return 'ชุดที่ดูเป็นทางการและเหมาะกับโอกาสพิเศษ'
